attempts.proposal:
SELECT ?assetIdentifier
WHERE {
  ?anchor <https://example.org/dexpi/hasAssetIdentifier> ?assetIdentifier .
  FILTER (isLiteral(?assetIdentifier) && datatype(?assetIdentifier) = xsd:string)
  FILTER (?anchor = <https://aas.example.com/TI101>)
} LIMIT 100

